    92→                pattern_type: "MemoryLeak".to_string(),
    93→                confidence,
    94→                description: "메모리 누수 감지 (포화도 지속 상승)".to_string(),
    95→            });
    96→            self.total_patterns_recognized += 1;
    97→        }
    98→
    99→        if let Some(confidence) = self.pattern_matcher.detect_io_bottleneck(metrics) {
   100→            detected.push(DetectedPattern {
   101→                pattern_type: "IOBottleneck".to_string(),
   102→                confidence,
   103→                description: "I/O 병목 감지 (ops >50k/sec)".to_string(),
   104→            });
   105→            self.total_patterns_recognized += 1;
   106→        }
   107→
   108→        if let Some(confidence) = self.pattern_matcher.detect_thread_contention(metrics) {
   109→            detected.push(DetectedPattern {
   110→                pattern_type: "ThreadContention".to_string(),
   111→                confidence,
   112→                description: "스레드 경합 감지 (CS >5M/sec)".to_string(),
   113→            });
   114→            self.total_patterns_recognized += 1;
   115→        }
   116→
   117→        if let Some(confidence) = self.pattern_matcher.detect_cache_thrashing(metrics) {
   118→            detected.push(DetectedPattern {
   119→                pattern_type: "CacheThreshing".to_string(),
   120→                confidence,
   121→                description: "캐시 쓰레싱 감지 (miss >30%)".to_string(),
   122→            });
   123→            self.total_patterns_recognized += 1;
   124→        }
   125→
   126→        if let Some(confidence) = self.pattern_matcher.detect_combined_pressure(metrics) {
   127→            detected.push(DetectedPattern {
   128→                pattern_type: "CombinedPressure".to_string(),
